import os
from pathlib import Path

import pytest


def read_public(path: str) -> str:
    """Return the text of the file `path` inside the directory `notes`
    (relative to the working directory), or "" if it cannot be read.

    `path` is untrusted. Subdirectories are allowed (`sub/b.txt`), and a
    path that wanders but stays inside `notes` (`sub/../a.txt`) is fine.
    Any path that resolves outside `notes` (`..`, an absolute path,
    `sub/../../x`, a symlink pointing outside, a sibling directory such
    as `../notes2/x.txt`) reads nothing and returns "". A missing,
    unreadable, non-file, or malformed name (e.g. containing a NUL
    byte) also returns "". Never raises.
    """
    if "\x00" in path:
        return ""
    try:
        requested = Path(path)
        if requested.is_absolute() or requested.anchor or requested.drive:
            return ""
        base = Path("notes").resolve()
        target = (base / requested).resolve()
        target.relative_to(base)
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8", errors="replace")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "sub" / "b.txt").write_text("beta")
    (tmp_path / "secret.txt").write_text("secret")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("sibling")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_simple_file(root: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_subdirectory_file(root: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_wander_and_return(root: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"
    assert read_public("./sub/./b.txt") == "beta"


def test_missing_file(root: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/nope.txt") == ""


def test_empty_and_directory(root: Path) -> None:
    assert read_public("") == ""
    assert read_public(".") == ""
    assert read_public("sub") == ""
    assert read_public("sub/") == ""


def test_parent_escape(root: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../x") == ""
    assert read_public("a.txt/../../secret.txt") == ""


def test_sibling_prefix_directory(root: Path) -> None:
    assert read_public("../notes2/x.txt") == ""


def test_absolute_path(root: Path) -> None:
    assert read_public(str(root / "secret.txt")) == ""
    assert read_public(str(root / "notes" / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""


def test_backslash_and_odd_names(root: Path) -> None:
    assert read_public("..\\secret.txt") == ""
    assert read_public("sub\\..\\..\\secret.txt") == ""


def test_nul_byte(root: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("\x00") == ""


def test_symlink_file_escape(root: Path) -> None:
    link = root / "notes" / "link.txt"
    try:
        link.symlink_to(root / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("link.txt") == ""


def test_symlink_dir_escape(root: Path) -> None:
    link = root / "notes" / "outdir"
    try:
        link.symlink_to(root / "notes2", target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("outdir/x.txt") == ""


def test_symlink_inside_notes_ok(root: Path) -> None:
    link = root / "notes" / "alias.txt"
    try:
        link.symlink_to(root / "notes" / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unsupported")
    assert read_public("alias.txt") == "alpha"


@pytest.mark.skipif(os.name == "nt", reason="posix permissions")
def test_unreadable_file(root: Path) -> None:
    f = root / "notes" / "locked.txt"
    f.write_text("hidden")
    f.chmod(0)
    try:
        if os.access(f, os.R_OK):
            pytest.skip("permissions not enforced (running as root)")
        assert read_public("locked.txt") == ""
    finally:
        f.chmod(0o600)


def test_non_utf8_does_not_raise(root: Path) -> None:
    (root / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00")
    assert isinstance(read_public("bin.dat"), str)

